#!/bin/bash
# Task 072 -- mesh-sorter: three of run_tests.sh's full-mode extras on meshsim branch v1.2-sort (WORKER8, after merging
# WORKER4's phase 3): CtrlTest -1 full, EngineTest -1 full, NetTest -1 skewtable 40, in parallel. Payload embedded below
# (meshsim.jar built from the branch, Java 17 bytecode; sw/build's images; data/; hops.txt; the branch's committed
# logs as references), SHA-256 checked. Passes if all three report 0 failed and the skew table equals the reference.
# Commits the three logs. Expected 10-20 min, about 12 GB.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/072-meshsorter-v12-extras; mkdir -p "$RES"
WANT=5468ae36ddea05dd15b5a805584f860689705d48023d8a4d15636de798e7dae9
W=/tmp/ms-072; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/k72.tgz" || exit 2
GOT=$(sha256sum "$W/k72.tgz" | cut -d' ' -f1); echo "payload sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "payload sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/k72.tgz" -C "$W" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
"$W/k72/run72.sh" "$W/out"; RC=$?
cp "$W"/out/*.log "$RES/" 2>/dev/null
echo "run72.sh exit $RC at $(date -u)"
exit $RC
